import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./SpendingPriority.css";

function SpendingPriority({ updateData }) {
  const navigate = useNavigate();

  const categories = [
    "Food & Groceries",
    "Shopping",
    "Bills",
    "Health",
    "Entertainment",
    "Transport"
  ];

  const [values, setValues] = useState({});

  const handleChange = (cat, val) => {
    setValues((prev) => ({ ...prev, [cat]: Number(val) }));
  };

  const handleContinue = () => {
    if (updateData) updateData({ spendingPriority: values });
    navigate("/budget");
  };

  return (
    <div className="income-container">
      <h2 className="income-title">Set Spending Priorities</h2>

      <div className="income-grid">
        {categories.map((cat) => (
          <div key={cat} className="income-card">
            <div className="income-name">{cat}</div>

            <input
              type="range"
              min="0"
              max="5"
              value={values[cat] || 0}
              onChange={(e) => handleChange(cat, e.target.value)}
              style={{ width: "100%", marginTop: "10px" }}
            />

            <div>{values[cat] || 0}</div>
          </div>
        ))}
      </div>

      <button className="next-button" onClick={handleContinue}>
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
